package com.smartexam.security;
import com.smartexam.entity.Users; import com.smartexam.service.UsersService; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter {
 private final JwtService jwtService; private final ApiAuthenticationEntryPoint entryPoint; private final UsersService users;
 public JwtAuthenticationFilter(JwtService jwtService,ApiAuthenticationEntryPoint entryPoint,UsersService users){this.jwtService=jwtService;this.entryPoint=entryPoint;this.users=users;}
 @Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{String h=request.getHeader("Authorization");if(h==null||!h.startsWith("Bearer ")){chain.doFilter(request,response);return;}try{var c=jwtService.parse(h.substring(7));Users user=users.findByUsername(c.getSubject());if(user==null||!Integer.valueOf(1).equals(user.getStatus())){SecurityContextHolder.clearContext();entryPoint.commence(request,response,null);return;}var auth=new UsernamePasswordAuthenticationToken(user.getUsername(),null,List.of(new SimpleGrantedAuthority("ROLE_"+user.getRole())));SecurityContextHolder.getContext().setAuthentication(auth);chain.doFilter(request,response);}catch(JwtException|IllegalArgumentException e){SecurityContextHolder.clearContext();entryPoint.commence(request,response,null);}}
 }
